 card(s,0.6,6.15,12.15,0.7,null,'V dan R menentukan apakah ada keunggulan. I dan N menentukan apakah keunggulan itu bertahan. Kebanyakan perusahaan hanya punya satu atau dua aset yang lolos semua.',{fill:NOTE,bs:12.5});
